#!/bin/sh
# Install the demo plugin for the current user (the phase-5 quickstart).
#
# Install layout (contract §1, packaging/plugin/README.md):
#   $XDG_DATA_HOME/deckstack/plugins/demo/        (default ~/.local/share/deckstack/plugins/demo/)
#     manifest.json    generated by make_manifest.py (command + fs_roots + resources)
#     plugin.py        the plugin itself
# The daemon's plugin host scans that directory and starts every <id>/manifest.json
# it finds, so the plugin is live after the next `ds daemon start` (or the first
# plugin step). `ds plugin install …` is a later-phase CLI verb; in this tree the
# install is exactly this copy + manifest.
#
# Usage: sh install.sh [dest-dir]
set -eu
HERE=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
DEST=${1:-${XDG_DATA_HOME:-$HOME/.local/share}/deckstack/plugins/demo}
mkdir -p "$DEST"
cp "$HERE/plugin.py" "$DEST/plugin.py"
python3 "$HERE/make_manifest.py" "$DEST/manifest.json"
echo "installed demo plugin to $DEST"
echo "start (or restart) the daemon, then trigger it, e.g.:"
echo "  ds bind deck/control/keys.0/down --do 'plugin demo.bump {\"by\":1}' --json"
